problems.reference_solution:
def pair_with_sum(nums, target):
    """Return (i, j), i < j, with nums[i] + nums[j] == target, or None."""
    left, right = 0, len(nums) - 1
    while left < right:
        total = nums[left] + nums[right]
        if total == target:
            return (left, right)
        if total < target:
            left += 1
        else:
            right -= 1
    return None

