problems.reference_solution:
def group_anagrams(words):
    """Return the words grouped into lists of anagrams, in order of first appearance."""
    groups = {}
    for word in words:
        groups.setdefault(''.join(sorted(word)), []).append(word)
    return list(groups.values())

