    """Return True when the brackets ()[]{} in text are balanced."""
    pass

problems.reference_solution:
def is_balanced(text):
    """Return True when the brackets ()[]{} in text are balanced."""
    closing = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif ch in closing:
            if not stack or stack.pop() != closing[ch]:
                return False
    return not stack

