class _Watched(list):
    """A list that counts element reads and refuses to be scanned."""

    def __init__(self, values):
        super().__init__(values)
        self.reads = 0

    def __getitem__(self, key):
        if isinstance(key, slice):
            raise AssertionError('slicing copies part of the list: read single elements by index')
        self.reads += 1
        return super().__getitem__(key)

    def _refuse(self, *args, **kwargs):
        raise AssertionError('scanning the list is linear: read single elements by index')

    __iter__ = __contains__ = __reversed__ = index = count = copy = _refuse


